import type {UserRecord} from "./user-record";

interface UserPreview {
  id: UserRecord["id"];
  displayName: UserRecord["displayName"];
}

export type {UserPreview};

.ui_themePreview {
  display: block;
}

.ant-tree .ant-tree-node-content-wrapper {
  color: #334155;
  padding: 8px 12px;
  border-radius: 6px;
}

.ant-tree .ant-tree-node-content-wrapper:hover {
  background: #334155;
  padding: 8px 12px;
  border-radius: 6px;
}

import "./_index.css";

interface CatalogEntry {
  id: string;
  label: string;
  active: boolean;
}

export const CatalogPage = ({entries}: {entries: CatalogEntry[]}) => (
  <nav className="route_catalog">
    {entries.map((entry) => (
      <button key={entry.id} className={entry.active ? "route_catalog__listButtonActive" : ""}>
        {entry.label}
      </button>
    ))}
  </nav>
);

.route_catalog__listButtonActive {
  display: flex;
  color: var(--color-accent);
  font-weight: 700;
}

.route_catalog__listButtonActive:hover {
  text-decoration: underline;
}

import {useMutation, useSuspenseQuery} from "@tanstack/react-query";

import {EntryList} from "./-local/entry-list";
import {fetchEntries, postEntry} from "./entry-api";

export const EntriesPage = () => {
  const entriesQuery = useSuspenseQuery({queryKey: ["entries"], queryFn: fetchEntries});
  const createEntry = useMutation({mutationFn: postEntry});
  const entries = entriesQuery.data.entries;
  const items = entries.map((entry) => ({id: entry.id, label: entry.title.trim()}));
  const meta = {total: entriesQuery.data.total};

  return <EntryList items={items} total={meta.total} onCreate={createEntry.mutate} />;
};

import clsx from "clsx";

interface UiEntryTreeProps {
  entries: Array<{id: string; label: string}>;
  selectedId?: string;
}

export const UiEntryTree = ({entries, selectedId}: UiEntryTreeProps) => (
  <ul className={clsx("ui_entryTree", selectedId && "ui_entryTree--selected")}>
    {entries.map((entry) => (
      <li key={entry.id}>{entry.label}</li>
    ))}
  </ul>
);

interface CreateEntryPayload {
  entryId: string;
  name: string;
  tags: string[];
  enabled: boolean;
}

const createEntryPayload = (
  entryId: string,
  name: string,
  tags: string[],
  enabled: boolean,
): CreateEntryPayload => ({
  entryId,
  name: name.trim(),
  tags,
  enabled,
});

export const EntriesPage = () => {
  const payload = createEntryPayload("entry-1", "Draft", ["new"], true);

  return <pre>{JSON.stringify(payload)}</pre>;
};

import clsx from "clsx";

import "./detail.css";

export const CatalogDetail = () => (
  <main className="route_catalogDetail">
    <section className={clsx("route_catalogDetail__section", "route_catalogDetail__section--compactTop")}>
      <h2>Summary</h2>
    </section>
  </main>
);

import {useEffect, useState} from "react";

interface Entry {
  id: string;
  label: string;
}

export const EntriesPage = ({entries}: {entries: Entry[]}) => {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [selectedCount, setSelectedCount] = useState(0);
  const [hasSelection, setHasSelection] = useState(false);

  useEffect(() => {
    setSelectedCount(selectedIds.length);
    setHasSelection(selectedIds.length > 0);
  }, [selectedIds]);

  return (
    <section>
      <p>{hasSelection ? `${selectedCount} selected` : "No selection"}</p>
      {entries.map((entry) => (
        <button
          key={entry.id}
          onClick={() => {
            setSelectedIds(
              selectedIds.includes(entry.id)
                ? selectedIds.filter((selectedId) => selectedId !== entry.id)
                : [...selectedIds, entry.id],
            );
          }}
        >
          {entry.label}
        </button>
      ))}
    </section>
  );
};
